const D = { energy:.55, scale:1, density:.5, speed:1, hue:44, weave:.6, border:.7, x:.5, y:.46, style:'rush', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, H = ((P.hue%360)+360)%360, en = cl(P.energy,0,1);
const sp = .25 + .75*P.speed;
const lift = .55 + .45*K.intensity;
const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);

if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;

// ---- a real tatami layout -------------------------------------------------
// Mats are dominoes on a 12x12 TORUS (so the plane repeats seamlessly in both
// directions with no fault line). The layout obeys the tatami condition --
// shugi-jiki, the auspicious layout -- in which four mats may never meet at a
// point. A vertex is bad exactly when its four cells belong to four DIFFERENT
// mats; if two of them share a mat, that mat runs THROUGH the vertex instead of
// cornering on it. Solved by exact backtracking that tries all four neighbours
// of the first empty cell, so mats crossing the torus seam are expressible
// (a search that only reaches right/down provably cannot tile the torus at all).
const Wg = 12, Hg = 12;
const wi = i => (((i%Wg)+Wg)%Wg), wj = j => (((j%Hg)+Hg)%Hg);
const idx = (i,j) => wi(i) + Wg*wj(j);
if (!S.own || S.seedUsed !== sd) {
  S.seedUsed = sd;
  const own = new Int16Array(Wg*Hg).fill(-1), doms = [];
  const vertOK = (i,j) => {
    const a=own[idx(i-1,j-1)], b=own[idx(i,j-1)], c=own[idx(i-1,j)], e=own[idx(i,j)];
    if (a<0||b<0||c<0||e<0) return true;
    return !(a!==b && a!==c && a!==e && b!==c && b!==e && c!==e);
  };
  const okAround = (i,j) => {
    for (let p=0;p<=1;p++) for (let q=0;q<=1;q++) if (!vertOK(i+p,j+q)) return false;
    return true;
  };
  const DIR = [[1,0],[0,1],[-1,0],[0,-1]];
  let steps = 0;
  const rec = pos => {
    if (steps++ > 900000) return false;
    while (pos < Wg*Hg && own[pos] >= 0) pos++;
    if (pos >= Wg*Hg) return true;
    const i = pos%Wg, j = (pos-i)/Wg;
    const o = [0,1,2,3];
    for (let k=3;k>0;k--){ const r = Math.floor(fr(pos*5.7 + k*13.1 + sd*.13)*(k+1)); const t = o[k]; o[k]=o[r]; o[r]=t; }
    for (let z=0;z<4;z++){
      const dx = DIR[o[z]][0], dy = DIR[o[z]][1];
      const ni = wi(i+dx), nj = wj(j+dy);
      if (own[idx(ni,nj)] >= 0) continue;
      const d = doms.length;
      doms.push({ i: dx<0?ni:i, j: dy<0?nj:j, h: dx!==0?1:0 });
      own[idx(i,j)] = d; own[idx(ni,nj)] = d;
      if (okAround(i,j) && okAround(ni,nj) && rec(pos)) return true;
      own[idx(i,j)] = -1; own[idx(ni,nj)] = -1; doms.pop();
    }
    return false;
  };
  if (!rec(0)) {                      // fallback: staggered columns are provably tatami-valid
    own.fill(-1); doms.length = 0;
    for (let i=0;i<Wg;i++) for (let k=0;k<Hg/2;k++){
      const j = (i%2) + 2*k, d = doms.length;
      doms.push({ i:i, j:wj(j), h:0 });
      own[idx(i,j)] = d; own[idx(i,j+1)] = d;
    }
  }
  S.own = own; S.doms = doms;
}
const own = S.own, doms = S.doms;

// ---- camera ---------------------------------------------------------------
const hz = cl(P.y,.24,.70)*height, cxp = cl(P.x,.15,.85)*width;
const gh = Math.max(24, height-hz);
const f = u*1.0, camH = cl(2.4/cl(P.scale,.5,2.2), .7, 6);
S.cz = (S.cz||0) + dt*sp*(.55 + .6*lift + .5*en)*.55;
S.cx = (S.cx||0) + dt*sp*(.05*Math.sin(K.t*.037) + .035*Math.sin(K.t*.091+1.4));
const camZ = S.cz, camX = S.cx;
const znear = f*camH/gh;
const NR = cl(Math.round(8 + cl(P.density,0,1)*6), 6, 14);
const zfar = znear + NR;
const PYo = Z => hz + f*camH/Z;
const PXo = (X,Z) => cxp + f*(X-camX)/Z;

// ---- styles ---------------------------------------------------------------
const glow = (sty==='xray');
function haze(){
  if (sty==='ink')     return [30, 6, 74];
  if (sty==='moonlit') return [222, 46, 22];
  if (glow)            return [(H+190)%360, 56, 6];
  if (sty==='worn')    return [38, 14, 62];
  return [(H+4)%360, 22, 58];
}
function matCol(lam, wv, jit, agei){
  const v = (.34 + .62*lam)*(.6+.5*en) + wv*.3;
  if (sty==='ink')     return [ 32, cl(5 + 6*jit,0,18), cl(28 + 58*v, 4, 92) ];
  if (sty==='moonlit') return [ (216 + jit*14)%360, cl(34 - 10*v,6,52), cl(16 + 52*v, 3, 82) ];
  if (glow)            return [ (H + 130 + jit*60)%360, 44, cl(14 + 86*v, 2, 100) ];
  if (sty==='worn')    return [ (40 + jit*16 - agei*10)%360, cl(24 + 16*jit - 10*agei, 5, 48), cl(38 + 50*v, 6, 94) ];
  return [ (H + jit*12 - 4)%360, cl(34 + 14*jit, 8, 62), cl(30 + 58*v, 5, 96) ];  // rush
}
const hc = haze(); const ic = glow ? [(H+150)%360, 30, 96] : [28, 30, 10];

const lang = K.t*.061*sp + .5*Math.sin(K.t*.0293+.7);
const lightZ = znear + 3.5 + 2.6*Math.sin(K.t*.083*sp) + 1.3*Math.sin(K.t*.191*sp+1.9);
const wv0 = cl(P.weave,0,1), bw = cl(P.border,0,1);

push();
// haze band under the horizon so the plane reads as receding, not as a flat wall
noStroke();
for (let i=0;i<9;i++){
  const q=i/8;
  fill(hc[0], hc[1], cl(hc[2]*(.7+.5*q),0,100), 100);
  if (i===0) rect(0, hz, width, gh);
}
strokeJoin(ROUND);
let drawn = 0;

for (let r=NR-1; r>=0 && drawn<240; r--){          // far -> near (painter)
  const Z0 = znear + r, Z1 = Z0 + 1;
  const gj = Math.floor(Z0 + camZ);
  const zA = gj - camZ, zB = zA + 1;
  if (zA < znear*.92) continue;
  const gi0 = Math.floor(camX - cxp*zB/f) - 2, gi1 = Math.ceil(camX + (width-cxp)*zB/f) + 1;
  if (gi1 - gi0 > 44) continue;
  for (let gi=gi0; gi<=gi1 && drawn<240; gi++){
    const d = doms[own[idx(gi,gj)]];
    if (!d) continue;
    if ((((gi%Wg)+Wg)%Wg) !== d.i || (((gj%Hg)+Hg)%Hg) !== d.j) continue;   // draw each mat from its origin cell only
    const wX = d.h ? 2 : 1, wZ = d.h ? 1 : 2;
    const X0 = gi, X1 = gi + wX, ZA = zA, ZB = zA + wZ;
    if (ZA < znear*.92) continue;
    const yA = PYo(ZA), yB = PYo(ZB);
    const aX0 = PXo(X0,ZA), aX1 = PXo(X1,ZA), bX0 = PXo(X0,ZB), bX1 = PXo(X1,ZB);
    if (Math.max(aX0,bX0) > width+40 || Math.min(aX1,bX1) < -40) continue;
    const fog = cl((zfar - ZA)/(zfar - znear), 0, 1);
    const fogq = fog*fog*(3-2*fog);
    const jit = fr(d.i*13.7 + d.j*29.3);
    const agei = fr(d.i*7.1 + d.j*3.9);
    const lam = cl(1 - Math.abs(ZA - lightZ)/4.2, 0, 1) * (.6+.5*lift);
    const wv = lam*(.5+.5*bass);
    const c = matCol(lam, wv, jit, agei);
    // the mat
    if (glow) {
      blendMode(ADD);
      noStroke(); fill(c[0], c[1], c[2], cl((8 + 22*lam)*fogq, 1, 44));
      quad(aX0,yA, aX1,yA, bX1,yB, bX0,yB);
      blendMode(BLEND);
      noFill(); stroke(c[0], c[1], cl(c[2],0,100), cl((30+50*lam)*fogq, 2, 92));
      strokeWeight((u/900)*(.6+1.2*en)); quad(aX0,yA, aX1,yA, bX1,yB, bX0,yB);
    } else {
      noStroke();
      fill(c[0], c[1], c[2], 100*fogq);
      quad(aX0,yA, aX1,yA, bX1,yB, bX0,yB);
      // igusa rush grain: fine lines running the mat's long axis
      const hpx = Math.abs(yA-yB);
      if (wv0 > .05 && hpx > 9) {
        stroke(c[0], cl(c[1]+16,0,100), cl(c[2]*.72,0,100), (16 + 40*wv0)*fogq);
        strokeWeight((u/1100)*(.4+.5*en));
        const nh = 3 + Math.round(wv0*5);
        for (let k2=1;k2<=nh;k2++){
          const t2 = k2/(nh+1);
          if (d.h) {   // long axis lateral -> grain runs across
            const yy = yA + (yB-yA)*t2;
            const xx0 = aX0 + (bX0-aX0)*t2, xx1 = aX1 + (bX1-aX1)*t2;
            line(xx0, yy, xx1, yy);
          } else {     // long axis into depth -> grain runs toward the horizon
            line(aX0 + (aX1-aX0)*t2, yA, bX0 + (bX1-bX0)*t2, yB);
